        return tuple(sorted((f, t)))

    old_parsed = [parse_edge(line) for line in old_lines]
    new_parsed = [parse_edge(line) for line in new_lines]

    old_roads = {get_key(f, t): k for f, t, k in old_parsed}
    new_roads = {get_key(f, t): k for f, t, k in new_parsed}

    added = []
    removed = []
    changed = []

    for f, t, k in new_parsed:
        key = get_key(f, t)
        if key not in old_roads:
            added.append((f, t, k))
        elif old_roads[key] != k:
            changed.append((f, t, k))

    for f, t, k in old_parsed:
